-- Faturamento 99 Food por loja, jan a out/2026, das planilhas "Detalhes da fatura" do portal
-- (Financeiro › Central de downloads), uma por loja e mês de cobrança.
-- BV = Bela Vista · BK = Brooklin (jan–abr sem pedidos no Brooklin)
-- Pode rodar mais de uma vez: substitui o mesmo mês × loja.
-- Em todas as linhas: vendas − promoções − comissão − anúncios + ajustes = soma do "Valor da cobrança".
-- Precisa do dre_canal_planilha.sql (origem 'planilha'), que já foi rodado.

ON CONFLICT (mes, canal, unidade) DO UPDATE SET
  vendas = EXCLUDED.vendas, promocoes = EXCLUDED.promocoes, taxas = EXCLUDED.taxas, servicos = EXCLUDED.servicos,
  marketing = EXCLUDED.marketing, ajustes = EXCLUDED.ajustes, total_faturamento = EXCLUDED.total_faturamento,
  unidade_print = EXCLUDED.unidade_print, detalhes = EXCLUDED.detalhes, origem = EXCLUDED.origem, atualizado_em = now();

-- Conferência: BV 10 meses, BK 6 meses; nao_fecha deve ser 0
SELECT unidade, count(*) AS meses, sum(vendas) AS vendas, sum(marketing) AS anuncios, sum(total_faturamento) AS recebido,
  count(*) FILTER (WHERE abs(vendas - promocoes - taxas - servicos - marketing + ajustes - total_faturamento) > 0.01) AS nao_fecha
FROM dre_canal_competencia WHERE canal = '99 Food' AND mes BETWEEN '2026-01' AND '2026-10'
GROUP BY unidade ORDER BY unidade;
